-- 141c786a | ما حكم مراجعة الزوج لزوجته بعد الطلاق الرجعي دون علمها؟
UPDATE qa_questions SET
  answer = 'صحيحة ولو لم تعلم الزوجة وقت المراجعة، بل نقل ابن قدامة فيه الإجماع لا قول الجمهور فحسب: «الرجعة لا تفتقر إلى ولي، ولا صداق، ولا رضى المرأة، ولا علمها، بإجماع أهل العلم»؛ لأن الرجعية في أحكام الزوجات، والرجعة إمساك لها واستبقاء لنكاحها، فلم تحتج إلى ما يحتاج إليه ابتداء النكاح. وأما الإشهاد على الرجعة فلا خلاف بين أهل العلم في أن السنّة الإشهاد عليها، وفي وجوبه روايتان عن الإمام أحمد: إحداهما تجب، وهي أحد قولي الشافعي؛ والثانية لا تجب وهي اختيار أبي بكر وقول مالك وأبي حنيفة، وعليها يُحمل الأمر بالإشهاد على الاستحباب.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١٠/ص٥٥٨ و٥٥٩ (مسألة قال: والمراجعة أن يقول لرجلين من المسلمين: اشهدا أني قد راجعت امرأتي) | الكلمات المفتاحية: مراجعة الطلاق الرجعي',
  evidence = 'المغني ج١٠/ص٥٥٨، ولفظ الخِرَقي: «الْمُرَاجَعَةُ أَنْ يَقُولَ لِرَجُلَيْنِ مِنَ الْمُسْلِمِينَ: اشْهَدَا أنّى قَدْ رَاجَعْتُ امْرَأَتِى. بِلَا وَلىٍّ يَحْضُرُهُ، وَلَا صَداقٍ يَزِيدُهُ»، قال ابن قدامة: «وَجُمْلَتُه أَنَّ الرَّجْعَةَ لَا تَفْتَقِرُ إلى وَلِىٍّ، ولا صَدَاقٍ، ولا رِضَى المَرْأَةِ، ولا عِلْمِها. بِإجْمَاعِ أَهْلِ العِلْمِ»؛ «لِمَا ذَكَرنَا مِنْ أَنَّ الرَّجْعِيَّةَ فى أَحْكامِ الزَّوْجَاتِ، والرَّجْعَةُ إِمْساكٌ لهَا، واسْتِبْقَاءٌ لِنِكَاحِها». وفي الإشهاد ج١٠/ص٥٥٩: «فَأَمَّا الشَّهَادَةُ ففيها رِوَايَتَانِ؛ إحْداهما، تَجِبُ. وهذا أَحَدُ قَوْلَىِ الشَّافِعِىِّ… والرِّوَايَةُ الثَّانِيَةُ، لا تَجِبُ الشَّهَادَةُ. وهى اخْتَيِارُ أَبى بكرٍ، وقَوْلُ مَالِكٍ، وأبى حَنِيفَةَ… وعِنْدَ ذلك يُحْمَلُ الأَمْرُ على الاسْتِحْبَابِ. ولا خِلَافَ بَيْنَ أَهْلِ العِلْمِ، فى أَنَّ السُّنَّةَ الإِشْهَادُ».',
  verification_status = 'verified'
WHERE id = '141c786a-a8ad-4c23-9522-710972419cfb'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: مراجعة الطلاق الرجعي'
  AND evidence = 'مسألة فقهية مبنية على أن الرجعة حق للزوج لا يحتاج رضا الزوجة أو علمها الفوري لصحتها.'
  AND answer = 'صحيحة عند جمهور الفقهاء ولو لم تعلم الزوجة وقت المراجعة، لكن يُستحب إعلامها فورًا لتستمر في أداء حقوق الزوجية.';

-- 2e6fd92c | ما حكم صيام النوافل خارج شهر رمضان؟
UPDATE qa_questions SET
  answer = 'صيام النفل مستحب مرغَّب فيه، وأفضله صيام داود عليه السلام: صوم يوم وإفطار يوم؛ ومنه صيام ثلاثة أيام من كل شهر وهو مستحب لا يُعلم فيه خلاف، وصيام الاثنين والخميس، ويوم عاشوراء ويوم عرفة، وست من شوال — وهذه مستحبة عند كثير من أهل العلم وبه قال الشافعي، وكرهها مالك خشية أن يُلحق برمضان ما ليس منه. ولا يُستحب صوم يوم عرفة لمن كان بعرفة، ليتقوّى على الدعاء. وأما يوما العيدين فصومهما محرَّم لا مكروه فحسب: فقد نهى النبي ﷺ عن صيام يومين — يوم الفطر ويوم الأضحى — والنهي يقتضي فساد المنهي عنه وتحريمه؛ وكذلك أيام التشريق منهيّ عن صيامها، لقوله ﷺ: "أيام التشريق أيام أكل وشرب".',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٤/ص٤٢٥ و٤٣٨ و٤٤٠ و٤٤٤ و٤٤٥ (كتاب الصيام) | الكلمات المفتاحية: صيام النفل',
  evidence = 'المغني ج٤/ص٤٣٨: «وجُمْلَةُ ذلك أنَّ صَوْمَ سِتَّةِ أَيَّامٍ من شَوَّال مُسْتَحَبٌّ عند كَثِيرٍ من أهْلِ العِلْمِ… وبه قال الشَّافِعِىُّ. وكَرِهَهُ مالِكٌ»، لحديث أبي أيوب: «مَنْ صَامَ رَمَضَانَ، وأَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ، فَكَأنَّمَا صَامَ الدَّهْرَ». وج٤/ص٤٤٠: «وجُمْلَتُه أنَّ صِيامَ هذَيْنِ اليَوْمَيْنِ مُسْتَحَبٌّ» يعني عاشوراء وعرفة، وج٤/ص٤٤٤: «ولا يُسْتَحَبُّ لِمَنْ كَانَ بِعَرَفَةَ أنْ يَصُومَ، لِيَتَقَوَّى عَلَى الدُّعَاءِ». وج٤/ص٤٤٥: «وأفْضَلُ الصِّيامِ أن تَصُومَ يَوْمًا وتُفْطِرَ يَوْمًا… فَذلِكَ صِيَامُ دَاوُدَ، وهُوَ أَفْضَلُ الصِّيَامِ» متفق عليه، وفيها أن النبي ﷺ «كان يَصُومُ يَوْمَ الاثْنَيْنِ والخَمِيسِ» رواه أبو داود، ثم: «وجُمْلَةُ ذلك أنَّ صِيامَ ثلاثةِ أيَّامٍ من كلِّ شَهْرٍ مُسْتَحَبٌّ، لا نَعْلَمُ فيه خِلافًا». وفي المنهيّ عنه ج٤/ص٤٢٥: «نَهَى عن صِيَامِ يَوْمَيْنِ؛ يَوم فِطْرٍ، ويَوْم أَضْحَى… والنَّهْىُ يَقْتَضِى فَسادَ المَنْهِىِّ عنه وتَحْرِيمَه»، و«وجُمْلَةُ ذلك أنَّ أيَّامَ التَّشْرِيقِ مَنْهِىٌّ عن صِيَامِها أيضا» لحديث نُبَيْشَة: «أيَّامُ التَّشْرِيقِ أيَّامُ أَكْلٍ وشُرْبٍ» رواه مسلم.',
  verification_status = 'verified'
WHERE id = '2e6fd92c-77ed-4559-a52c-3c712db41359'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: صيام النفل'
  AND evidence = 'أحاديث متعددة في فضل صيام النفل، مبسوطة في كتب الفقه والسنن.'
  AND answer = 'صيام النفل مستحب مرغَّب فيه في أوقات كثيرة (كست شوال، وعرفة، وعاشوراء، والاثنين والخميس)، ويُكره أو يُمنع في أوقات معدودة كيومي العيدين وأيام التشريق.';

-- 5a45478a | كم مرة تجب فيها كفارة اليمين إذا تكرر الحلف على أمر واحد؟
UPDATE qa_questions SET
  answer = 'إذا كرّر الحلف على الأمر الواحد ثم حنث فليس عليه إلا كفارة واحدة عند الحنابلة، وروي نحوه عن ابن عمر، وبه قال الحسن وعروة وإسحاق؛ لأن الحنث واحد أوجب جنسًا واحدًا من الكفارات فلم يجب به أكثر من كفارة. وليس هذا قول الجمهور، ولا هو مقيَّد باتحاد المجلس: فأصحاب الرأي والثوري وأبو ثور يوجبون لكل يمين كفارة إلا أن يريد التأكيد والتفهيم، وللشافعي قولان كالمذهبين، وانفرد عمرو بن دينار بالتفريق بين المجلس الواحد والمجالس. وأما إذا حلف أيمانًا على أجناس مختلفة — كأن يقول: والله لا أكلت، والله لا شربت، والله لا لبست — فحنث في الجميع قبل التكفير، فعليه في كل يمين كفارة، وهو ظاهر كلام الخِرَقي وقول أكثر أهل العلم.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١٣/ص٤٧٣ و٤٧٤ (مسألة قال: ولو حلف بهذه الأشياء كلها على شيء واحد فحنث فعليه كفارة واحدة) | الكلمات المفتاحية: تكرار كفارة اليمين',
  evidence = 'المغني ج١٣/ص٤٧٣: «كرَّرَ اليَمِينَ على شىءٍ واحدٍ، مثل إن قال: واللَّهِ لأَغْزُوَنّ قُرَيْشًا، واللَّهِ لأَغزُوَنّ قُرَيْشًا، واللَّهِ لأَغْزُوَنّ قُرَيشًا. فحَنِثَ، فليس عليه إِلَّا كَفَارةٌ واحِدةٌ. رُوِىَ نحوُ هذا عن ابنِ عمرَ. وبه قال الحسَنُ، وعُرْوَةُ، وإسحاقُ… وقال أصحابُ الرَّأْىِ: عليه لِكُلِّ يَمِينٍ كَفّارَةٌ، إلَّا أَنْ يُريدَ التَّأْكيدَ والتَّفْهِيمَ. ونحوُه عن الثَّوْرِىِّ، وأبى ثَوْرٍ. وعن الشافِعِىِّ قَوْلان، كالمَذْهَبَيْن. وعن عمرِو بنِ دينارٍ، إنْ كان فى مَجْلِسٍ واحدٍ كقَوْلِنا، وإِنْ كان فى مجالِسَ كَقَوْلِهم»، ثم دليلُه: «ولَنا، أنَّه حِنْثٌ واحِدٌ أوجَبَ جِنْسًا واحدًا من الكَفَّاراتِ، فلم يجبْ بِه أكثرُ من كَفَّارَةٍ، كما لو قصدَ التَّأْكِيدَ والتَّفْهيمَ». وج١٣/ص٤٧٤ في الأيمان على أجناس مختلفة: «وإِنْ حَنِثَ فى الجميعِ قبلَ التَّكْفيرِ، فعليه فى كُلِّ يَمِينٍ كفارَةٌ. هذا ظاهِرُ كلامِ الْخِرَقِىِّ. وروَاه الْمَرُّوذِىُّ عن أحمدَ. وهو قولُ أكثرِ أهلِ العِلْمِ».',
  verification_status = 'verified'
WHERE id = '5a45478a-db35-4744-a61b-55bea1baf96e'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: تكرار كفارة اليمين'
  AND evidence = 'مسألة فقهية مبسوطة في كتب الفقه.'
  AND answer = 'كفارة واحدة تكفي إذا كان الحلف المتكرر على نفس الأمر في مجلس واحد لم يتخللها كفارة، عند جمهور الفقهاء، ما لم يقصد تعدد الأيمان.';

-- 6934b828 | ما أبرز شروط القاضي في الإسلام؟
UPDATE qa_questions SET
  answer = 'يُشترط في القاضي عند الحنابلة ثلاثة شروط: الأول الكمال، وهو نوعان — كمال الأحكام: أن يكون بالغًا عاقلًا حرًّا ذكرًا؛ وكمال الخِلقة: أن يكون متكلمًا سميعًا بصيرًا. والثاني العدالة، فلا تجوز تولية فاسق ولا من فيه نقص يمنع الشهادة. والثالث أن يكون من أهل الاجتهاد، وبه قال مالك والشافعي وبعض الحنفية. ومقتضى ذلك أنه لا يكفي أن يكون عاميًّا يحكم بالتقليد، خلافًا لمن أجازه؛ لقوله تعالى: ﴿وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ﴾ ولم يقل بالتقليد، ولحديث بريدة: "القضاة ثلاثة؛ اثنان في النار، وواحد في الجنة… ورجل قضى للناس على جهل فهو في النار"، والعامي يقضي على جهل. والإسلام معتبر كذلك، كما نصّ عليه الخِرَقي في شروطه.',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج١٤/ص١٢ و١٣ و١٤ (مسألة قال: ولا يولى قاض حتى يكون بالغًا عاقلًا مسلمًا حرًّا عدلًا عالمًا فقيهًا ورعًا) | الكلمات المفتاحية: شروط القاضي، أدب القضاء',
  evidence = 'المغني ج١٤/ص١٢، ولفظ الخِرَقي: «وَلَا يُوَلَّى قَاضٍ حَتَّى يَكُونَ بَالِغًا، عَاقِلًا، مُسْلِمًا، حُرًّا، عَدْلًا، عَالِمًا، فَقِيهًا، وَرِعًا»، قال ابن قدامة: «وجُمْلتُه أنَّه يُشْتَرطُ في القاضي ثَلاثةُ شروطٍ؛ أحدها، الكَمالُ، وهو نوعان؛ كمالُ الأحْكام، وكمالُ الخِلْقَةِ، أمَّا كمالُ الأحكامِ فيُعتَبرُ في أربعةِ أشياء؛ أنْ يكونَ بَالغًا عاقِلًا حُرًّا ذكَرًا». وج١٤/ص١٣: «وأما كمالُ الخِلْقةِ، فأنْ يكونَ مُتَكلِّمًا سميعًا بصيرًا؛ لأنَّ الأخْرَسَ لا يُمْكِنُه النُّطْقُ بالحُكْمِ… والأصَمَّ لا يَسْمعُ قولَ الخَصْمَينِ، والأعْمَى لا يعْرِفُ المُدَّعِىَ مِن المُدَّعَى عليه»، و«الشرط الثاني، العدالةُ، فلا يجوزُ تَوْلِيَةُ فاسقٍ، ولا مَن فيه نَقْصٌ يَمْنَعُ الشَّهادةَ». وج١٤/ص١٤: «الشرط الثالث، أنْ يكونَ من أهلِ الاجْتهادِ. وبهذا قال مالكٌ، والشافعيُّ، وبعضُ الحنفيَّةِ. وقالَ بعضُهم: يجوزُ أن يكونَ عامِّيًّا فيَحْكمَ بالتَّقْليدِ… ولَنا، قولُ اللهِ تعالى: ﴿وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ﴾. ولم يقُلْ بالتَّقْليدِ»، وحديث بريدة: «القُضَاةُ ثَلَاثَةٌ؛ اثْنَانِ فِي النَّارِ، وَوَاحِدٌ فِي الْجَنَّةِ… وَرَجُلٌ قَضَى لِلنَّاسِ عَلَى جَهْلٍ، فَهُوَ فِي النَّارِ» رواه ابن ماجه، «والعامِّيُّ يقْضِي على الجَهْلِ».',
  verification_status = 'verified'
WHERE id = '6934b828-f91b-4579-abe6-dc4255d076ab'
  AND reference = 'كتب الفقه الإسلامي | الكلمات المفتاحية: شروط القاضي، أدب القضاء'
  AND evidence = 'مسألة فقهية مبسوطة في كتب أدب القضاء.'
  AND answer = 'الإسلام والبلوغ والعقل والعدالة والعلم بأحكام القضاء (اجتهادًا أو معرفة أقوال أهل العلم)، والسلامة من موانع الشهادة المعتبرة.';

-- 8033995f | ما حقوق الأبناء على الوالدين؟
UPDATE qa_questions SET
  answer = 'من حقوقهم المقرَّرة في كتب الفقه: الإنفاق عليهم، وهو واجب أجمع عليه كل من يُحفظ عنه من أهل العلم في حق الأولاد الأطفال الذين لا مال لهم، لقوله ﷺ لهند: "خذي ما يكفيك وولدك بالمعروف". والتسوية بينهم في العطية، وهي واجبة والتفضيل فيها محرَّم لا مكروه فحسب، لأن النبي ﷺ سمّاه جورًا وأمر بردّه وامتنع عن الشهادة عليه. وإعفافهم بالتزويج إذا كانت نفقتهم على الأب واحتاجوا إليه، نصّ عليه أصحاب الإمام أحمد. ويُستحب أن يُحسن اسمه، لقوله ﷺ: "إنكم تُدعون يوم القيامة بأسمائكم وأسماء آبائكم فأحسنوا أسماءكم".',
  reference = 'المغني لابن قدامة، ت التركي والحلو: ج٨/ص٢٥٧ وج١١/ص٣٧٣ و٣٨٠ وج١٣/ص٣٩٨ (العطية والنفقات والعقيقة) | الكلمات المفتاحية: حقوق الأبناء',
  evidence = 'المغني ج١١/ص٣٧٣ في النفقة: «أجْمَعَ كلُّ مَنْ نَحْفَظُ عنه من أهلِ العلمِ، على أنَّ على المَرْءِ نَفَقةَ أوْلادِه الأطْفالِ الذين لا مالَ لهم»، ومن السنة قوله ﷺ لهند: «خُذِى مَا يَكْفِيكِ وَوَلَدَكِ بِالمَعْرُوفِ» متفق عليه. وفي التسوية بينهم ج٨/ص٢٥٧، من حديث النعمان بن بشير أن النبي ﷺ قال لأبيه: «أكُلَّ وَلَدِكَ أعْطَيْتَ مِثْلَه؟» قال: لا. قال: «فَاتَّقُوا اللهَ، وَاعْدِلُوا بَيْنَ أَوْلَادِكُمْ»، قال ابن قدامة: «وهو دَلِيلٌ على التَّحْرِيمِ؛ لأنَّه سَمَّاهُ جَوْرًا، وأمَرَ بِرَدِّه، وامْتَنَعَ من الشَّهَادَةِ عليه، والجَوْرُ حَرَامٌ، والأمْرُ يَقْتَضِى الوُجُوبَ». وفي التزويج ج١١/ص٣٨٠: «قال أصحابُنا: وعلى الأبِ إعْفافُ ابْنِه إذا كانت عليه نفَقَتُه، وكان مُحْتاجًا إلى إعْفافِه». وفي الاسم ج١٣/ص٣٩٨: «ويُستَحَبُّ أَنْ يُحْسِنَ اسمَه؛ لأَنَّه رُوِىَ عن النَّبِىِّ ﷺ أنَّه قال: "إِنَّكُم تُدْعَوْنَ يومَ القيامَةِ بِأسْمَائِكُمْ، وأسْماءِ آبائِكُمْ، فَأَحْسِنُوا أسْمَاءَكُمْ"».',
